// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    // fuzzed params: from address, number of recipients (n), and a dummy value seed
    // we will construct arrays of length n and pass them; the helper will accept the low-level calls
    function testFuzz_property(address from, uint256 n, uint256 seed) public {
        // keep n in a reasonable range but allow >0 to be tested broadly
        uint256 len = bound(n, 0, 8);
        vm.assume(len > 0); // admissible domain requires _tos.length > 0 per contract

        // deploy a recording helper that implements transferFrom(address,address,uint256)
        Recorder rec = new Recorder();

        // build arrays of addresses and values of length `len`
        address[] memory tos = new address[](len);
        uint256[] memory vals = new uint256[](len);
        for (uint i = 0; i < len; i++) {
            // derive pseudo-random addresses/values from seed to let fuzzer explore space
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i, from)))));
            vals[i] = uint256(keccak256(abi.encodePacked(seed, i, from))) & ((1 << 120) - 1);
        }

        // call transfer and capture whether it succeeds (reference must always succeed for these inputs)
        bool ok;
        try c.transfer(from, address(rec), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for any admissible input (_tos.length > 0), the correct contract
        // completes transfer (ok == true). The mutant with i <= _tos.length will sometimes revert
        // due to out-of-bounds access; thus assert that the call did not revert.
        assertTrue(ok);
    }
}

// Recorder: records each call to transferFrom(address,address,uint256) so that c's outgoing calls
// are a well-formed external interaction. It always returns true (mimicking a successful callee).
contract Recorder {
    event Called(address from, address to, uint256 v);
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Called(from, to, v);
        return true;
    }
}
